// generated by plugin/scripts/build.mjs from cli/src (piezas 0.7.4); do not edit by hand
// Part of the piezas CLI (see index.js).
//
// ===========================================================================
// The once-a-day "newer version" notice
// ===========================================================================
//
// `npx piezas <cmd>` does not always run the newest Piezas tools: inside a
// project it runs the project's own copy (node_modules/piezas, by design: the
// guardrails run from it), and outside one a global install (`npm install -g
// piezas`) wins over npx and never updates. So once a day the CLI asks npm
// for the newest version and, when this copy is older, prints ONE line on
// stderr with the fix for where this copy lives (a project, the computer's
// global folder, or npx's cache).
//
// Never in the way:
//   - skipped in CI, with PIEZAS_NO_UPDATE_CHECK=1, from the plugin's own copy
//     (the plugin updates itself), for help and usage errors, and for the hook
//     commands (`phase hook` / `phase guard`: their stderr is the hook's answer);
//   - the command never waits for the check: the notice comes only from the
//     answer saved in the Piezas home folder (update-check.json next to the
//     sign-in, PIEZAS_HOME when set) as { checkedAt, latest }. When that is
//     missing or over 24 hours old, a detached background process
//     (updaterefresh.js) asks npm and saves the new answer for the next run,
//     so the check runs at most once a day. It is a separate process because
//     a DNS lookup cannot be cancelled: an unreachable resolver would keep
//     this one alive after its work is done. That process ends within about
//     5 s whatever happens;
//   - any failure means no notice, and counts as that day's check;
//   - stdout is never written, so --json output stays valid.
import { spawn } from 'child_process';
import { mkdirSync, readFileSync, realpathSync, writeFileSync } from 'fs';
import { homedir } from 'os';
import { dirname, join, resolve } from 'path';
import { fileURLToPath } from 'url';
import { CLI_VERSION, piezasHomeDir } from './constants.js';
import { parseCliArgs } from './core.js';
import { runningFromPlugin } from './guards.js';
import { fetchJson } from './platform.js';

export const UPDATE_CHECK_URL = 'https://registry.npmjs.org/piezas/latest';
// In the background process: the request's own timeout, and the moment the
// process exits whatever is still pending.
export const UPDATE_CHECK_TIMEOUT_MS = 4000;
export const UPDATE_REFRESH_LIMIT_MS = 5000;
export const UPDATE_CHECK_MAX_AGE_MS = 24 * 60 * 60 * 1000;
export const UPDATE_CHECK_FILE = 'update-check.json';

// The commands main() runs. Anything else (no command, help, a typo) is help
// or a usage error: no check.
export const UPDATE_CHECK_COMMANDS = new Set([
  'init', 'import', 'login', 'logout', 'whoami', 'status', 'logs', 'undeploy', 'deploy',
  'reports', 'unattended', 'report-button', 'env', 'preview', 'connect', 'phase', 'spec',
  'test', 'quality-scan', 'doctor',
]);

const PLAIN_VERSION = /^(\d+)\.(\d+)\.(\d+)$/;
const THIS_FILE = fileURLToPath(import.meta.url);
// The background process's entry, next to this file.
export const UPDATE_REFRESH_ENTRY = join(dirname(THIS_FILE), 'updaterefresh.js');

// updateCheckSkipped — why no check runs for these arguments, or null.
export function updateCheckSkipped(argv = process.argv, { env = process.env, fromPlugin } = {}) {
  if (env.CI !== undefined && env.CI !== '') return 'ci';
  const off = String(env.PIEZAS_NO_UPDATE_CHECK ?? '').trim();
  if (off !== '' && !/^(0|false|no)$/i.test(off)) return 'off';
  if (fromPlugin ?? runningFromPlugin()) return 'plugin';
  const command = argv[2];
  const rest = argv.slice(3);
  if (!UPDATE_CHECK_COMMANDS.has(command) || rest.some((a) => a === '--help' || a === '-h')) return 'usage';
  if (command === 'phase') {
    const sub = parseCliArgs(rest).positional[0];
    if (sub === 'hook' || sub === 'guard') return 'hook';
  }
  return null;
}

// newerVersion — is `latest` a newer x.y.z than `current`? Pre-releases and
// anything that is not a plain x.y.z never count.
export function newerVersion(latest, current) {
  const a = PLAIN_VERSION.exec(String(latest ?? '').trim());
  const b = PLAIN_VERSION.exec(String(current ?? '').trim());
  if (!a || !b) return false;
  for (let i = 1; i <= 3; i += 1) {
    const x = Number(a[i]);
    const y = Number(b[i]);
    if (x !== y) return x > y;
  }
  return false;
}

// --- the saved answer ------------------------------------------------------------

export function updateCachePath(env = process.env) {
  return join(piezasHomeDir(env), UPDATE_CHECK_FILE);
}

// { checkedAt (ms), latest (x.y.z or null) }, or null when there is none.
export function readUpdateCache(env = process.env) {
  try {
    const data = JSON.parse(readFileSync(updateCachePath(env), 'utf-8'));
    const checkedAt = Date.parse(data?.checkedAt);
    if (!Number.isFinite(checkedAt)) return null;
    const latest = typeof data.latest === 'string' && PLAIN_VERSION.test(data.latest) ? data.latest : null;
    return { checkedAt, latest };
  } catch {
    return null;
  }
}

export function writeUpdateCache(env, checkedAt, latest) {
  try {
    const file = updateCachePath(env);
    mkdirSync(dirname(file), { recursive: true, mode: 0o700 });
    writeFileSync(file, `${JSON.stringify({ checkedAt: new Date(checkedAt).toISOString(), latest: latest ?? null }, null, 2)}\n`);
    return true;
  } catch {
    return false;
  }
}

// fetchLatestVersion — the newest piezas on npm (a credential-free GET through
// the CLI's network gate), or null. Network errors and timeouts throw.
export async function fetchLatestVersion(fetchFn = globalThis.fetch, timeoutMs = UPDATE_CHECK_TIMEOUT_MS) {
  const { status, data } = await fetchJson(fetchFn, UPDATE_CHECK_URL, { timeoutMs });
  const version = status === 200 && typeof data?.version === 'string' ? data.version.trim() : '';
  return PLAIN_VERSION.test(version) ? version : null;
}

// --- where this copy lives ----------------------------------------------------------

function realish(p) {
  try {
    return realpathSync(p);
  } catch {
    return resolve(p);
  }
}

const slashes = (p) => String(p).replace(/\\/g, '/');

// npm's own value for `${NAME}` and a leading `~` in an npmrc path.
function expandNpmrcPath(value, env, home) {
  const v = value.replace(/^["']|["']$/g, '').replace(/\$\{([^}]+)\}/g, (_, name) => env[name] ?? '');
  return /^~(?=$|[\\/])/.test(v) ? join(home, v.slice(1)) : v;
}

// npmGlobalPrefixes — the places npm's global folder can be, read the way npm
// reads them, without starting npm: the prefix npm passes to what it runs
// (npx, npm exec), npm_config_prefix, the prefix= line of the user's npmrc,
// PREFIX, and node's own install folder (npm's default).
export function npmGlobalPrefixes({ env = process.env, platform = process.platform, execPath = process.execPath, home = homedir() } = {}) {
  const out = [];
  const add = (p) => {
    if (typeof p === 'string' && p.trim()) out.push(p.trim());
  };
  add(env.npm_config_global_prefix);
  add(env.npm_config_prefix);
  try {
    const rc = readFileSync(env.npm_config_userconfig || join(home, '.npmrc'), 'utf-8');
    const m = /^[ \t]*prefix[ \t]*=[ \t]*(.+?)[ \t]*$/m.exec(rc);
    if (m) add(expandNpmrcPath(m[1], env, home));
  } catch { /* no npmrc */ }
  add(env.PREFIX);
  if (platform === 'win32') {
    if (env.APPDATA) add(join(env.APPDATA, 'npm'));
    add(dirname(execPath));
  } else {
    add(dirname(dirname(execPath)));
  }
  return out;
}

function declaresPiezas(projectDir) {
  try {
    const pkg = JSON.parse(readFileSync(join(projectDir, 'package.json'), 'utf-8'));
    return ['dependencies', 'devDependencies', 'optionalDependencies'].some((f) => Boolean(pkg?.[f]?.piezas));
  } catch {
    return false;
  }
}

// copyKind — where the running piezas lives, by the real path of this file:
//   'npx'     — npx's cache (an `_npx` folder);
//   'global'  — npm's global folder: under <prefix>/lib/node_modules (on
//               Windows <prefix>/node_modules) for any prefix npm would use,
//               or a `lib/node_modules/piezas` with no project above it;
//   'project' — a project's node_modules: the folder holding node_modules
//               has a package.json that declares piezas, and it is not npm's
//               global folder (that folder never has one);
//   'other'   — anything else (a checkout, a link, another tool's global folder).
// Only 'project' sends the owner to change a project folder (npm install -D
// in it), so it is the strictest.
export function copyKind(modulePath = THIS_FILE, options = {}) {
  const platform = options.platform ?? process.platform;
  const path = slashes(realish(modulePath));
  if (path.includes('/_npx/')) return 'npx';
  if (!path.includes('/node_modules/piezas/')) return 'other';
  const fold = (s) => (platform === 'win32' || platform === 'darwin' ? s.toLowerCase() : s);
  const here = fold(path);
  for (const prefix of npmGlobalPrefixes({ ...options, platform })) {
    const p = fold(slashes(realish(prefix))).replace(/\/+$/, '');
    if (here.startsWith(`${p}/lib/node_modules/piezas/`)) return 'global';
    if (platform === 'win32' && here.startsWith(`${p}/node_modules/piezas/`)) return 'global';
  }
  const owner = path.slice(0, path.indexOf('/node_modules/'));
  // yarn, pnpm and bun keep their global installs in a folder named global
  // that looks like a project: not a project folder.
  if (/\/global(?:\/\d+)?$/.test(owner)) return 'other';
  if (declaresPiezas(owner)) return 'project';
  if (path.includes('/lib/node_modules/piezas/')) return 'global';
  return 'other';
}

// updateNotice — the one line, for where this copy lives. A project's copy is
// the owner's to update: the guardrails refuse an AI command that changes it.
export function updateNotice(latest, current, kind) {
  if (kind === 'project') {
    return `  A newer version of the Piezas tools is out (${latest}; this project has ${current}). To update, run this in your own terminal, in the project folder: npm install -D piezas@${latest}  (For the AI: you can't run this yourself; tell the owner in one sentence.)`;
  }
  if (kind === 'global') {
    return `  A newer version of the Piezas tools is out (${latest}; this computer has an older copy, ${current}, installed for all folders). Remove it so npx always fetches the newest: npm uninstall -g piezas`;
  }
  return `  A newer version of the Piezas tools is out (${latest}; this is ${current}). Run it as npx piezas@latest followed by the command, for example: npx piezas@latest doctor`;
}

// spawnUpdateRefresh — start the background process that asks npm and saves
// the answer: detached, no input or output, not waited for. Never throws.
export function spawnUpdateRefresh(env = process.env, spawnFn = spawn) {
  try {
    const child = spawnFn(process.execPath, [UPDATE_REFRESH_ENTRY], { detached: true, stdio: 'ignore', env, windowsHide: true });
    child?.on?.('error', () => {});
    child?.unref?.();
    return true;
  } catch {
    return false;
  }
}

// startUpdateCheck — called as a command starts: when the saved answer is
// missing or stale, starts the background refresh (once). Returns { finish }:
// finish() prints the notice (at most one line, on stderr) once the command
// is done, from the saved answer only (none: no notice this run). Never
// throws, never waits for the network. Options (tests): argv, env, now,
// spawnFn, current, modulePath, fromPlugin, write, and copyKind's platform /
// execPath / home.
export function startUpdateCheck(options = {}) {
  const idle = { finish: async () => {} };
  try {
    const env = options.env ?? process.env;
    if (updateCheckSkipped(options.argv ?? process.argv, { env, fromPlugin: options.fromPlugin })) return idle;
    const now = options.now ?? Date.now;
    const current = options.current ?? CLI_VERSION;
    const write = options.write ?? ((line) => process.stderr.write(`${line}\n`));
    const cache = readUpdateCache(env);
    const age = cache ? now() - cache.checkedAt : Number.POSITIVE_INFINITY;
    const fresh = cache !== null && age >= 0 && age < UPDATE_CHECK_MAX_AGE_MS;
    if (!fresh) spawnUpdateRefresh(env, options.spawnFn ?? spawn);
    return {
      async finish() {
        try {
          // The saved answer decides this run, a stale one too.
          const latest = cache?.latest ?? null;
          if (!newerVersion(latest, current)) return;
          const kind = copyKind(options.modulePath ?? THIS_FILE, {
            env, platform: options.platform, execPath: options.execPath, home: options.home,
          });
          write(updateNotice(latest, current, kind));
        } catch { /* a notice is never worth a failure */ }
      },
    };
  } catch {
    return idle;
  }
}
